<?php
declare(strict_types=1);require_once __DIR__.'/includes/init.php';require_role('encargado','docente');$pageTitle=is_encargado()?'Tickets de mi turno':'Mis tickets';$p=db();$term=trim((string)($_GET['q']??''));$estado=trim((string)($_GET['estado']??''));$urg=trim((string)($_GET['urgencia']??''));$allowedStates=['abierto','en_revision','en_proceso','resuelto','cerrado'];$allowedUrg=['baja','media','alta','critica'];
$sql="SELECT t.id,t.tipo_problema,t.urgencia,t.estado,t.creado_en,t.turno_id,tr.nombre turno,CONCAT(u.nombre,' ',u.apellido) docente,s.nombre sala,COALESCE(e.codigo_inventario,'Sin equipo') equipo FROM tickets t JOIN usuarios u ON u.id=t.docente_id JOIN turnos tr ON tr.id=t.turno_id JOIN salas s ON s.id=t.sala_id LEFT JOIN equipos e ON e.id=t.equipo_id WHERE 1=1";$params=[];if(is_docente()){$sql.=' AND t.docente_id=:d';$params['d']=current_user()['id'];}else{$sql.=' AND t.turno_id=:t';$params['t']=manager_turn_id();}if($term!==''){$like='%'.$term.'%';$sql.=" AND (CAST(t.id AS CHAR) LIKE :q OR t.descripcion LIKE :q2 OR s.nombre LIKE :q3 OR e.codigo_inventario LIKE :q4 OR CONCAT(u.nombre,' ',u.apellido) LIKE :q5)";$params+=['q'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like,'q5'=>$like];}if(in_array($estado,$allowedStates,true)){$sql.=' AND t.estado=:estado';$params['estado']=$estado;}if(in_array($urg,$allowedUrg,true)){$sql.=' AND t.urgencia=:urg';$params['urg']=$urg;}$sql.=" ORDER BY FIELD(t.estado,'abierto','en_revision','en_proceso','resuelto','cerrado'),FIELD(t.urgencia,'critica','alta','media','baja'),t.creado_en DESC";$s=$p->prepare($sql);$s->execute($params);$rows=$s->fetchAll();require __DIR__.'/includes/header.php';?>
<section class="card"><div class="card-header"><div><h2>Listado de tickets</h2><?php if(is_encargado()):?><p class="meta mt-0">Turno <?=e(manager_turn_name())?></p><?php endif;?></div><?php if(is_docente()):?><a class="btn btn-primary btn-small" href="<?=e(url('docente/nuevo_ticket.php'))?>">Nuevo ticket</a><?php endif;?></div><div class="card-body"><form method="get" class="filter-bar"><div class="form-group"><label>Buscar</label><input name="q" value="<?=e($term)?>" placeholder="Ticket, sala, equipo..."></div><div class="form-group"><label>Estado</label><select name="estado"><option value="">Todos</option><?php foreach($allowedStates as $v):?><option value="<?=e($v)?>" <?=$estado===$v?'selected':''?>><?=e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach;?></select></div><div class="form-group"><label>Urgencia</label><select name="urgencia"><option value="">Todas</option><?php foreach($allowedUrg as $v):?><option value="<?=e($v)?>" <?=$urg===$v?'selected':''?>><?=e(ucfirst($v))?></option><?php endforeach;?></select></div><button class="btn btn-secondary">Filtrar</button><a class="btn btn-secondary" href="<?=e(url('tickets.php'))?>">Limpiar</a></form></div><div class="table-wrap"><?php if(!$rows):?><div class="empty-state">No hay tickets para esos filtros.</div><?php else:?><table><thead><tr><th>ID</th><th>Problema</th><th>Sala / Equipo</th><?php if(is_encargado()):?><th>Docente</th><?php else:?><th>Turno</th><?php endif;?><th>Urgencia</th><th>Estado</th><th>Fecha</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=(int)$r['id']?></td><td><?=e(ucwords(str_replace('_',' ',$r['tipo_problema'])))?></td><td><?=e($r['sala'])?><div class="meta"><?=e($r['equipo'])?></div></td><?php if(is_encargado()):?><td><?=e($r['docente'])?></td><?php else:?><td><?=e($r['turno'])?></td><?php endif;?><td><?=status_badge($r['urgencia'])?></td><td><?=status_badge($r['estado'])?></td><td><?=e(format_datetime($r['creado_en']))?></td><td><a class="btn btn-secondary btn-small" href="<?=e(url('ticket.php?id='.(int)$r['id']))?>">Abrir</a></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
